      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C24", "C29"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the supplied records.",
    "No exact same-scaffold reference context is present; the closest structural context is safinamide.",
